        if (d.id === id) res(d.result.result.value);
      };
      ws.send(JSON.stringify({ id, method: "Runtime.evaluate", params: { expression: code, returnByValue: true } }));
    });
  }

  const result = await evaluate(`(() => {
    document.documentElement.style.cssText = "width: 1920px; height: 1080px; overflow: hidden; margin: 0; padding: 0;";
    document.body.style.cssText = "width: 1920px; height: 1080px; overflow: hidden; margin: 0; padding: 0;";

    const app = document.createElement("div");
    app.id = "app";
    app.style.cssText = "position: relative; width: 1920px; height: 1080px; overflow: hidden;";
    document.body.appendChild(app);

    const bgBlur = document.createElement("img");
    bgBlur.id = "bgBlur";
    bgBlur.style.cssText = "position: fixed; top: -60px; left: -60px; width: calc(100% + 120px); height: calc(100% + 120px); object-fit: cover; filter: blur(28px); opacity: 0; pointer-events: none;";
    app.appendChild(bgBlur);

    const shade = document.createElement("div");
    shade.id = "shade";
    shade.style.cssText = "position: fixed; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none;";
    app.appendChild(shade);

    return {
      docScrollWidth: document.documentElement.scrollWidth,
      bodyScrollWidth: document.body.scrollWidth,
      appScrollWidth: app.scrollWidth
    };
  })()`);

  console.log("Measured ScrollWidths:", result);
  ws.close();
  chrome.kill();
}
test().catch(console.error);
